-- Enable UUID extension
create extension if not exists "uuid-ossp";

-- USERS TABLE
create table if not exists users (
  id text primary key,
  handle text unique,
  email text,
  name text,
  avatar text,
  reputation integer default 0,
  level integer default 1,
  daily_streak integer default 0,
  badges jsonb default '[]'::jsonb,
  active_location jsonb,
  friends jsonb default '[]'::jsonb,
  raw_data jsonb,
  updated_at timestamptz default now()
);

-- CUSTOM SPOTS TABLE
create table if not exists custom_spots (
  id text primary key,
  name text not null,
  district_id text,
  created_by text,
  description text,
  difficulty text default 'medium',
  hype integer default 0,
  coords jsonb,
  raw_data jsonb,
  created_at timestamptz default now()
);

-- DIRECT MESSAGES TABLE
create table if not exists direct_messages (
  id text primary key,
  sender_uid text,
  sender_handle text,
  receiver_uid text,
  text text,
  raw_data jsonb,
  created_at timestamptz default now()
);

-- CHALLENGES TABLE
create table if not exists challenges (
  id text primary key,
  title text not null,
  description text,
  district_id text,
  target_spot text,
  user_id text,
  creator_id text,
  difficulty text,
  type text,
  xp_reward integer default 100,
  status text default 'active',
  raw_data jsonb,
  created_at timestamptz default now()
);

-- WAWOLO RADIO TRACKS TABLE
create table if not exists wawoloradio_tracks (
  id text primary key,
  title text not null,
  artist text not null,
  url text,
  duration numeric,
  order_index integer,
  uploaded_by text,
  is_uploaded boolean default true,
  created_at timestamptz default now()
);

-- SKATE VIDEOS TABLE
create table if not exists skate_videos (
  id text primary key,
  spot_id text,
  spot_name text,
  skater_handle text,
  video_url text,
  trick_name text,
  raw_data jsonb,
  created_at timestamptz default now()
);


